mapper.update:
UPDATE user_video
play_time = #{playTime}, played_at = #{playedAt},
WHERE vid = #{vid} AND uid = #{uid}

UPDATE user_video
liked = #{liked}, unliked = #{unliked}, liked_at = #{likedAt},
WHERE vid = #{vid} AND uid = #{uid}

UPDATE user_video
coin = #{coin}, coined_at = #{coinedAt},
WHERE vid = #{vid} AND uid = #{uid}

UPDATE user_video
SET collect = #{collect}
WHERE vid = #{vid}
  AND uid = #{uid}
  AND collect != #{collect}
